<script setup lang="ts">
import{ref,watch,onMounted}from'vue';
const props=defineProps<{stockId:string;issuedAt:string;issueId?:string|null;modelValue:string[];disabled?:boolean}>(),emit=defineEmits(['update:modelValue','recipients','periods']);const items=ref<any[]|null>(null),busy=ref(false),error=ref('');
watch(()=>[props.stockId,props.issuedAt,props.issueId],()=>{items.value=null;error.value='';emit('update:modelValue',[]);emit('recipients',[]);emit('periods',[]);});
async function inspect(){busy.value=true;error.value='';const captured=[props.stockId,props.issuedAt,props.issueId].join('|');try{if(!props.issuedAt)throw Error('请先填写真实领用时间。');const q=new URLSearchParams({issuedAt:props.issuedAt});if(props.issueId)q.set('issueId',props.issueId);const r=await fetch('/api/v1/inventory/stocks/'+props.stockId+'/issue-options?'+q,{credentials:'same-origin'}),b=await r.json();if(!r.ok)throw Error(b.message||'未取得领用核对资料。');if(captured!==[props.stockId,props.issuedAt,props.issueId].join('|'))return;items.value=b.items;emit('recipients',b.recipients);emit('periods',b.items);emit('update:modelValue',[]);}catch(e){error.value=e instanceof Error?e.message:'领用核对失败。';}finally{busy.value=false;}}
function choose(id:string,checked:boolean){emit('update:modelValue',checked?[...props.modelValue.filter(x=>x!==id),id]:props.modelValue.filter(x=>x!==id));}onMounted(inspect);
</script>
<template><div class="ia-box"><button type="button" class="b-button outline small" :disabled="disabled||busy" @click="inspect">{{busy?'正在核对…':'核对实际时点人员与季度要求'}}</button><p v-if="error" role="alert">{{error}}</p><p v-if="items?.length===0">领用所属季度尚未确认，无需选择调整轮次。人员按实际领用日期核对。</p><article v-for="q in items||[]" :key="q.quarterId"><strong>{{q.label}}</strong><template v-if="q.canWrite"><p>总部当前事项：{{q.reason}}</p><label class="b-checkbox"><input type="checkbox" :disabled="disabled" :checked="modelValue.includes(q.adjustmentId)" @change="choose(q.adjustmentId,($event.target as HTMLInputElement).checked)"/><span>已核对本次领用补正，明确采用本季度当前调整轮次。</span></label></template><p v-else>{{q.status==='pending_review'?'已有待复核调整版，须先由总部退回，再补正领用来源。':'该季度已有确认结果，须先由总部记录针对最新确认结果的调整事项。'}}</p></article><p class="b-help">时间改变后请重新核对。数量更正只作用差额，补成本不再扣库存；牙医成本归属仍由季度核算核实。</p></div></template>
<style scoped>.ia-box{margin:16px 0;padding:16px;border:1px solid #dce7da;background:#f5f8f0;border-radius:10px}.ia-box p{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.ia-box article{padding-top:12px;margin-top:12px;border-top:1px solid #dce7da}</style>
